package com.orcamobile.app.glass;

import android.app.Activity;
import android.graphics.Color;
import android.os.Bundle;
import android.text.Editable;
import android.text.InputType;
import android.text.TextWatcher;
import android.view.Gravity;
import android.view.View;
import android.widget.EditText;
import android.widget.FrameLayout;
import android.widget.HorizontalScrollView;
import android.widget.LinearLayout;
import android.widget.ProgressBar;
import android.widget.ScrollView;
import android.widget.TextView;
import android.widget.Toast;
import com.orcamobile.app.R;

/** Phase-one component gallery. Example values never leave this Activity. */
public final class GlassGalleryActivity extends Activity {
    private FrameLayout root;private GlassUi ui;private LinearLayout content;private Bundle values=new Bundle();
    private int tab,nav,reference;private boolean reduced;private String group="Quality",preferenceSection="General";private boolean objects;
    @Override public void onCreate(Bundle state){super.onCreate(state);if(state!=null){tab=state.getInt("tab",0);nav=state.getInt("nav",0);reference=state.getInt("reference",0);reduced=state.getBoolean("reduced",false);objects=state.getBoolean("objects",false);group=state.getString("group","Quality");preferenceSection=state.getString("pref_section","General");Bundle restored=state.getBundle("sample_values");if(restored!=null)values=restored;}render();}
    @Override protected void onSaveInstanceState(Bundle state){state.putInt("tab",tab);state.putInt("nav",nav);state.putInt("reference",reference);state.putBoolean("reduced",reduced);state.putBoolean("objects",objects);state.putString("group",group);state.putString("pref_section",preferenceSection);state.putBundle("sample_values",new Bundle(values));super.onSaveInstanceState(state);}
    private String s(int id){return getString(id);}
    private void render(){
        root=new FrameLayout(this);root.setBackground(GlassBackground.create(this));setContentView(root);getWindow().setStatusBarColor(Color.rgb(74,79,89));getWindow().setNavigationBarColor(Color.rgb(74,79,89));getWindow().getDecorView().setSystemUiVisibility(0);
        if(android.os.Build.VERSION.SDK_INT>=35)root.setOnApplyWindowInsetsListener((v,in)->{android.graphics.Insets safe=in.getInsets(android.view.WindowInsets.Type.systemBars()|android.view.WindowInsets.Type.displayCutout());v.setPadding(safe.left,safe.top,safe.right,safe.bottom);return in;});
        ui=new GlassUi(this,root,reduced);if(reference!=0){renderReference();return;}LinearLayout column=ui.vertical();root.addView(column,new FrameLayout.LayoutParams(-1,-1));
        LinearLayout header=ui.horizontal();ui.pad(header,16,8,16,4);TextView title=ui.heading(s(R.string.glass_gallery_title));header.addView(title,new LinearLayout.LayoutParams(0,-2,1));android.widget.ImageView close=new android.widget.ImageView(this);close.setImageDrawable(GlassIcon.create(this,"close",ui.tokens.textPrimary));close.setBackground(GlassSurface.of(this,ui.tokens.pillRadiusMax,reduced));close.setContentDescription(s(R.string.glass_dismiss));close.setPadding(ui.dp(12),ui.dp(12),ui.dp(12),ui.dp(12));close.setFocusable(true);close.setOnClickListener(v->finish());header.addView(close,new LinearLayout.LayoutParams(ui.dp(48),ui.dp(48)));column.addView(header);
        LinearLayout tabs=ui.horizontal();ui.pad(tabs,16,0,16,0);int[] ids={R.string.glass_tab_components,R.string.glass_tab_process,R.string.glass_tab_preferences};for(int i=0;i<ids.length;i++){final int selected=i;View chip=ui.chip(s(ids[i]),tab==i,()->{tab=selected;render();});LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-2,-2);lp.rightMargin=ui.dp(6);tabs.addView(chip,lp);}HorizontalScrollView tabScroll=new HorizontalScrollView(this);tabScroll.setHorizontalScrollBarEnabled(false);tabScroll.addView(tabs);column.addView(tabScroll,new LinearLayout.LayoutParams(-1,-2));
        ScrollView scroll=new ScrollView(this);scroll.setFillViewport(false);scroll.setVerticalScrollBarEnabled(false);content=ui.vertical();ui.pad(content,(int)ui.tokens.screenPadding,12,(int)ui.tokens.screenPadding,24);scroll.addView(content);column.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
        TextView note=ui.text(s(R.string.glass_gallery_note),12,400,ui.tokens.textSecondary);content.addView(note);ui.space(content,12);if(tab==0)components();else if(tab==1)process();else preferences();
        GlassNavigation navigation=new GlassNavigation(this,nav,reduced,item->{nav=item;});LinearLayout.LayoutParams navParams=new LinearLayout.LayoutParams(-1,-2);navParams.setMargins(ui.dp(ui.tokens.navInset),ui.dp(8),ui.dp(ui.tokens.navInset),ui.dp(ui.tokens.navBottom));column.addView(navigation,navParams);
    }
    @Override public void onBackPressed(){if(reference!=0){reference=0;render();}else super.onBackPressed();}
    private void referenceMode(int mode){reference=mode;render();}
    private void renderReference(){
        LinearLayout column=ui.vertical();ui.pad(column,20,28,20,0);root.addView(column,new FrameLayout.LayoutParams(-1,-1));
        FrameLayout bar=new FrameLayout(this);column.addView(bar,new LinearLayout.LayoutParams(-1,ui.dp(44)));
        TextView title=ui.heading(s(reference==1?R.string.glass_tab_process:R.string.glass_preferences));title.setGravity(Gravity.CENTER);FrameLayout.LayoutParams titleLp=new FrameLayout.LayoutParams(-2,-1,Gravity.CENTER);bar.addView(title,titleLp);
        android.widget.ImageView back=new android.widget.ImageView(this);back.setImageDrawable(GlassIcon.create(this,"back",ui.tokens.textPrimary));back.setBackground(GlassSurface.of(this,ui.tokens.pillRadiusMax,reduced));back.setPadding(ui.dp(12),ui.dp(12),ui.dp(12),ui.dp(12));back.setContentDescription(s(R.string.glass_back));back.setFocusable(true);back.setOnClickListener(v->referenceMode(0));bar.addView(back,new FrameLayout.LayoutParams(ui.dp(44),ui.dp(44),Gravity.START|Gravity.CENTER_VERTICAL));
        if(reference==1){TextView save=ui.action(s(R.string.glass_save),true,()->Toast.makeText(this,R.string.glass_saved,Toast.LENGTH_SHORT).show());bar.addView(save,new FrameLayout.LayoutParams(-2,ui.dp(44),Gravity.END|Gravity.CENTER_VERTICAL));}
        ui.space(column,12);
        content=ui.vertical();if(reference==1)process();else preferences();
        content.removeViewAt(0);content.removeViewAt(0);
        int controls=reference==1?2:1;
        for(int i=0;i<controls;i++){View child=content.getChildAt(0);content.removeViewAt(0);column.addView(child,new LinearLayout.LayoutParams(-1,-2));}
        content.removeViewAt(0);ui.pad(content,0,0,0,110);
        ScrollView scroll=new ScrollView(this);scroll.setClipToPadding(false);scroll.setVerticalScrollBarEnabled(false);scroll.addView(content);column.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
        GlassNavigation navigation=new GlassNavigation(this,reference==1?1:3,reduced,item->{if(item==1)referenceMode(1);else if(item==3)referenceMode(2);else render();});FrameLayout.LayoutParams np=new FrameLayout.LayoutParams(-1,ui.dp(ui.tokens.navHeight),Gravity.BOTTOM);np.setMargins(ui.dp(20),0,ui.dp(20),ui.dp(24));root.addView(navigation,np);
    }
    private void header(int stringId){TextView section=ui.section(s(stringId));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(ui.dp(4),ui.dp(12),ui.dp(4),ui.dp(6));content.addView(section,lp);}
    private LinearLayout card(){return ui.vertical();}
    private void addCard(LinearLayout rows){content.addView(ui.surface(rows,ui.tokens.cardRadius),new LinearLayout.LayoutParams(-1,-2));}
    private void addRow(LinearLayout rows,View row){
        if(rows.getChildCount()>0){FrameLayout previous=(FrameLayout)rows.getChildAt(rows.getChildCount()-1);View divider=new View(this);divider.setBackgroundColor(ui.tokens.rowDivider);divider.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);previous.addView(divider,new FrameLayout.LayoutParams(-1,Math.max(1,ui.dp(1)),Gravity.BOTTOM));}
        FrameLayout wrapper=new FrameLayout(this);wrapper.addView(row,new FrameLayout.LayoutParams(-1,-2));rows.addView(wrapper,new LinearLayout.LayoutParams(-1,-2));
    }
    private GlassSwitch toggle(String key,int title,boolean initial){GlassSwitch v=new GlassSwitch(this);v.setContentDescription(s(title));v.setChecked(values.getBoolean(key,initial));v.setOnCheckedChangeListener((button,checked)->values.putBoolean(key,checked));return v;}
    private View toggleRow(String key,int title,boolean initial){return ui.row(s(title),toggle(key,title,initial),null);}
    private void watch(EditText field,String key){field.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int d){}public void onTextChanged(CharSequence s,int st,int before,int count){values.putString(key,s.toString());}public void afterTextChanged(Editable e){}});}
    private View numberRow(String key,int label,String initial,int unit){LinearLayout trailing=ui.horizontal();EditText field=ui.edit(values.getString(key,initial),InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL|InputType.TYPE_NUMBER_FLAG_SIGNED,false);field.setGravity(Gravity.END);field.setContentDescription(s(label));watch(field,key);trailing.addView(field,new LinearLayout.LayoutParams(ui.dp(58),-2));if(unit!=0){TextView suffix=ui.text(s(unit),12,500,ui.tokens.textSecondary);LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(-2,-2);sp.leftMargin=ui.dp(4);trailing.addView(suffix,sp);}return ui.row(s(label),trailing,null);}
    private View numberOrPercentRow(){LinearLayout controls=ui.horizontal();EditText number=ui.edit(values.getString("percentage","15"),InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL|InputType.TYPE_NUMBER_FLAG_SIGNED,false);number.setContentDescription(s(R.string.glass_percentage));number.setGravity(Gravity.END);watch(number,"percentage");controls.addView(number,new LinearLayout.LayoutParams(ui.dp(58),-2));boolean percent=values.getBoolean("percent_mode",true);TextView unit=ui.action(s(percent?R.string.glass_unit_percent:R.string.glass_unit_mm),false,null);unit.setOnClickListener(v->{boolean next=!values.getBoolean("percent_mode",true);values.putBoolean("percent_mode",next);unit.setText(s(next?R.string.glass_unit_percent:R.string.glass_unit_mm));unit.performHapticFeedback(android.view.HapticFeedbackConstants.VIRTUAL_KEY);});unit.setContentDescription(s(R.string.glass_change_unit));controls.addView(unit,new LinearLayout.LayoutParams(ui.dp(48),-2));return ui.row(s(R.string.glass_percentage),controls,null);}
    private View textRow(String key,int label,String initial,boolean multiline){EditText edit=ui.edit(values.getString(key,initial),InputType.TYPE_CLASS_TEXT,multiline);edit.setContentDescription(s(label));watch(edit,key);return ui.stackedRow(s(label),edit);}
    private View chooseRow(String key,int title,String[] options,int initial){int selection=Math.max(0,Math.min(options.length-1,values.getInt(key,initial)));TextView current=ui.value(options[selection]+"  ›");return ui.row(s(title),current,()->GlassBottomSheet.choose(this,root,reduced,s(title),options,values.getInt(key,initial),index->{values.putInt(key,index);current.setText(options[index]+"  ›");}));}
    private View actionRow(int title){TextView end=ui.action(s(R.string.glass_action_button),false,()->GlassBottomSheet.info(this,root,reduced,s(R.string.glass_location_title),s(R.string.glass_location_body)));return ui.row(s(title),end,null);}
    private void components(){
        content.addView(ui.action(s(R.string.glass_reference_process),false,()->referenceMode(1)));ui.space(content,6);
        content.addView(ui.action(s(R.string.glass_reference_preferences),false,()->referenceMode(2)));ui.space(content,16);
        header(R.string.glass_section_controls);LinearLayout settings=card();GlassSwitch transparency=new GlassSwitch(this);transparency.setContentDescription(s(R.string.glass_reduce_transparency));transparency.setChecked(reduced);transparency.setOnCheckedChangeListener((button,checked)->{reduced=checked;render();});addRow(settings,ui.row(s(R.string.glass_reduce_transparency),transparency,null));addRow(settings,toggleRow("support",R.string.glass_toggle,false));addCard(settings);
        LinearLayout chips=ui.horizontal();chips.addView(ui.chip(s(R.string.glass_chip_one),!objects,()->{objects=false;render();}));chips.addView(ui.chip(s(R.string.glass_chip_two),objects,()->{objects=true;render();}));content.addView(chips);ui.space(content,12);
        header(R.string.glass_section_rows);LinearLayout rows=card();addRow(rows,numberRow("number",R.string.glass_number,"0.20",R.string.glass_unit_mm));addRow(rows,numberOrPercentRow());
        addRow(rows,chooseRow("enum",R.string.glass_enum,new String[]{s(R.string.glass_aligned),s(R.string.glass_nearest),s(R.string.glass_random)},0));addRow(rows,textRow("string",R.string.glass_string,s(R.string.glass_text_example),false));addRow(rows,textRow("multi",R.string.glass_multiline,s(R.string.glass_filename_example),true));addRow(rows,actionRow(R.string.glass_action));
        LinearLayout combo=ui.horizontal();EditText seconds=ui.edit(values.getString("seconds","10"),InputType.TYPE_CLASS_NUMBER,false);seconds.setContentDescription(s(R.string.glass_combo));seconds.setGravity(Gravity.END);watch(seconds,"seconds");combo.addView(seconds,new LinearLayout.LayoutParams(ui.dp(48),-2));TextView sec=ui.text(s(R.string.glass_unit_seconds),12,500,ui.tokens.textSecondary);combo.addView(sec);combo.addView(toggle("auto_backup",R.string.glass_combo,true));addRow(rows,ui.row(s(R.string.glass_combo),combo,null));addCard(rows);
        content.addView(ui.action(s(R.string.glass_info_title),false,()->GlassBottomSheet.info(this,root,reduced,s(R.string.glass_info_title),s(R.string.glass_info_body))));ui.space(content,16);
        header(R.string.glass_section_states);LinearLayout states=card();ProgressBar progress=new ProgressBar(this);progress.setIndeterminateTintList(android.content.res.ColorStateList.valueOf(ui.tokens.textPrimary));addRow(states,ui.row(s(R.string.glass_state_loading),progress,null));addRow(states,ui.row(s(R.string.glass_state_empty),ui.value(s(R.string.glass_state_empty_detail)),null));addRow(states,ui.row(s(R.string.glass_state_error),ui.action(s(R.string.glass_state_retry),false,()->Toast.makeText(this,R.string.glass_state_demo,Toast.LENGTH_SHORT).show()),null));addRow(states,ui.row(s(R.string.glass_state_offline),ui.value(s(R.string.glass_state_offline_detail)),null));View disabled=ui.row(s(R.string.glass_state_disabled),toggle("disabled",R.string.glass_state_disabled,false),null);disabled.setEnabled(false);disabled.setAlpha(.5f);if(disabled instanceof LinearLayout){LinearLayout row=(LinearLayout)disabled;for(int i=0;i<row.getChildCount();i++)row.getChildAt(i).setEnabled(false);}addRow(states,disabled);addCard(states);
    }
    private void process(){
        LinearLayout top=ui.horizontal();top.addView(ui.heading(s(R.string.glass_tab_process)),new LinearLayout.LayoutParams(0,-2,1));top.addView(ui.action(s(R.string.glass_save),true,()->Toast.makeText(this,R.string.glass_saved,Toast.LENGTH_SHORT).show()));content.addView(top);ui.space(content,12);
        LinearLayout toggles=ui.horizontal();toggles.addView(ui.chip(s(R.string.glass_chip_one),!objects,()->{objects=false;render();}));toggles.addView(ui.chip(s(R.string.glass_chip_two),objects,()->{objects=true;render();}));TextView advanced=ui.text(s(R.string.glass_advanced),12,500,ui.tokens.textSecondary);LinearLayout.LayoutParams ad=new LinearLayout.LayoutParams(0,-2,1);ad.leftMargin=ui.dp(8);toggles.addView(advanced,ad);toggles.addView(toggle("advanced",R.string.glass_advanced,true));content.addView(toggles);
        HorizontalScrollView scroll=new HorizontalScrollView(this);scroll.setHorizontalScrollBarEnabled(false);LinearLayout chips=ui.horizontal();int[] labels={R.string.glass_quality,R.string.glass_strength,R.string.glass_speed,R.string.glass_support,R.string.glass_multimaterial,R.string.glass_others};String[] keys={"Quality","Strength","Speed","Support","Multimaterial","Others"};for(int i=0;i<labels.length;i++){String key=keys[i];chips.addView(ui.chip(s(labels[i]),group.equals(key),()->{group=key;render();}));}scroll.addView(chips);content.addView(scroll);ui.space(content,12);
        if(!group.equals("Quality")){LinearLayout examples=card();switch(group){
            case "Strength":addRow(examples,numberRow("wall_loops",R.string.glass_wall_loops,"2",0));addRow(examples,numberRow("density",R.string.glass_infill_density,"15",R.string.glass_unit_percent));break;
            case "Speed":addRow(examples,numberRow("outer_speed",R.string.glass_outer_wall_speed,"200",R.string.glass_unit_speed));break;
            case "Support":addRow(examples,toggleRow("support_page",R.string.glass_toggle,false));break;
            case "Multimaterial":addRow(examples,toggleRow("prime_tower",R.string.glass_prime_tower,true));break;
            default:addRow(examples,textRow("notes",R.string.glass_notes,"",true));break;
        }addCard(examples);return;}
        header(R.string.glass_section_layer_height);LinearLayout heights=card();addRow(heights,numberRow("layer_height",R.string.glass_number,"0.2",R.string.glass_unit_mm));addRow(heights,numberRow("first_height",R.string.glass_first_layer_height,"0.2",R.string.glass_unit_mm));addCard(heights);
        header(R.string.glass_section_line_width);LinearLayout widths=card();int[] names={R.string.glass_width_default,R.string.glass_width_first,R.string.glass_width_outer,R.string.glass_width_inner,R.string.glass_width_top,R.string.glass_width_sparse,R.string.glass_width_solid,R.string.glass_width_support};for(int i=0;i<names.length;i++)addRow(widths,numberRow("width_"+i,names[i],i==1?"0.5":(i==3||i==5?"0.45":"0.42"),R.string.glass_unit_mm));addCard(widths);
        header(R.string.glass_section_seam);LinearLayout seam=card();addRow(seam,chooseRow("seam",R.string.glass_enum,new String[]{s(R.string.glass_aligned),s(R.string.glass_nearest),s(R.string.glass_random)},0));addRow(seam,toggleRow("staggered",R.string.glass_staggered,false));addRow(seam,numberRow("gap",R.string.glass_seam_gap,"15",R.string.glass_unit_percent));addCard(seam);
    }
    private void preferences(){
        content.addView(ui.heading(s(R.string.glass_preferences)));ui.space(content,8);HorizontalScrollView strip=new HorizontalScrollView(this);strip.setHorizontalScrollBarEnabled(false);LinearLayout chips=ui.horizontal();int[] names={R.string.glass_pref_general,R.string.glass_pref_control,R.string.glass_pref_online,R.string.glass_pref_associate,R.string.glass_pref_developer};String[] keys={"General","Control","Online","Associate","Developer"};for(int i=0;i<names.length;i++){String key=keys[i];chips.addView(ui.chip(s(names[i]),preferenceSection.equals(key),()->{preferenceSection=key;render();}));}strip.addView(chips);content.addView(strip);ui.space(content,8);
        if(!preferenceSection.equals("General")){LinearLayout example=card();if(preferenceSection.equals("Control"))addRow(example,toggleRow("reverse_zoom",R.string.glass_reverse_zoom,false));else if(preferenceSection.equals("Online"))addRow(example,toggleRow("offline",R.string.glass_state_offline,false));else if(preferenceSection.equals("Associate"))addRow(example,actionRow(R.string.glass_associations));else addRow(example,toggleRow("developer",R.string.glass_developer_mode,false));addCard(example);return;}
        header(R.string.glass_section_general);LinearLayout general=card();addRow(general,chooseRow("lang",R.string.glass_language,new String[]{s(R.string.glass_english)},0));addRow(general,chooseRow("unit",R.string.glass_units,new String[]{s(R.string.glass_metric)},0));addRow(general,chooseRow("home",R.string.glass_default_page,new String[]{s(R.string.glass_home),s(R.string.glass_workspace)},0));addRow(general,toggleRow("dark",R.string.glass_enable_dark,true));addRow(general,toggleRow("single_instance",R.string.glass_single_instance,false));addRow(general,toggleRow("splash",R.string.glass_splash,true));addRow(general,actionRow(R.string.glass_download_folder));addCard(general);
        header(R.string.glass_section_project);LinearLayout project=card();addRow(project,chooseRow("load",R.string.glass_load_behavior,new String[]{s(R.string.glass_ask_when_needed)},0));addRow(project,numberRow("recent",R.string.glass_recent_count,"18",0));addRow(project,toggleRow("recent_models",R.string.glass_recent_models,false));addRow(project,toggleRow("no_warning",R.string.glass_no_warning,false));addRow(project,toggleRow("import_step",R.string.glass_import_step,true));LinearLayout backup=ui.horizontal();backup.addView(ui.text("10 sec",12,400,ui.tokens.textSecondary));backup.addView(toggle("backup",R.string.glass_backup,true));addRow(project,ui.row(s(R.string.glass_backup),backup,null));addCard(project);
        header(R.string.glass_preset);LinearLayout preset=card();addRow(preset,toggleRow("remember_printer",R.string.glass_remember_printer,true));addRow(preset,chooseRow("group_filament",R.string.glass_group_filament,new String[]{s(R.string.glass_none)},0));addCard(preset);
    }
}

